#!/usr/bin/env node
// Embeds frpc (gzip+base64) for pkg builds. Mirrors cloudflared/ffmpeg bundle
// generation because pkg asset globs are unreliable for node20 targets.

'use strict';

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const crypto = require('crypto');
const { parseOptions } = require('./lib/binary-target');

const ROOT = path.resolve(__dirname, '..');

function bundleBinary(name, file) {
  if (!fs.existsSync(file)) throw new Error(`${name} not found at ${file}`);
  const raw = fs.readFileSync(file);
  return {
    b64: zlib.gzipSync(raw, { level: 9 }).toString('base64'),
    hash: crypto.createHash('sha256').update(raw).digest('hex'),
    size: raw.length,
  };
}

function generateFrpBundle(options = {}) {
  const platform = options.platform || process.platform;
  const arch = options.arch || process.arch;
  const inputDir = path.resolve(options['input-dir'] || options.inputDir || path.join(ROOT, 'vendor', 'frp'));
  const output = path.resolve(options.output || path.join(ROOT, 'src', 'frp-bundle.js'));
  const binName = platform === 'win32' ? 'frpc.exe' : 'frpc';
  const frpc = bundleBinary('frpc', path.join(inputDir, binName));

  const lines = [
    '// AUTO-GENERATED by scripts/generate-frp-bundle.js - do not edit by hand.',
    "'use strict';",
    '',
    'module.exports = {',
    `  platform: ${JSON.stringify(platform)},`,
    `  arch: ${JSON.stringify(arch)},`,
    `  frpc: { data: Buffer.from(${JSON.stringify(frpc.b64)}, 'base64'), sha256: ${JSON.stringify(frpc.hash)}, compressed: true },`,
    '};',
    '',
  ];
  fs.mkdirSync(path.dirname(output), { recursive: true });
  fs.writeFileSync(output, lines.join('\n'), 'utf8');
  return { output, inputDir, platform, arch, frpc };
}

if (require.main === module) {
  try {
    const result = generateFrpBundle(parseOptions(process.argv.slice(2)));
    console.log(`Generated ${result.output} for ${result.platform}/${result.arch}.`);
  } catch (err) {
    console.error(`ERROR: ${err.message}`);
    process.exit(1);
  }
}

module.exports = { generateFrpBundle };
